const m=String(msg.topic||"").match(/^RX-CNT\/([^/]+)\/telemetry$/);
if (!m) return null;

const id="RX-CNT-"+m[1];
const cfg=global.get("counterConfig")||{};
if (!cfg[id] || cfg[id].enabled!==true) return null;

if (flow.get("counterRestoreReady")!==true || flow.get("downtimeRestoreReady")!==true) {
    const pending=flow.get("pendingCounterTelemetry")||{};
    pending[id]={topic:msg.topic,payload:msg.payload};
    flow.set("pendingCounterTelemetry",pending);
    return null;
}
return msg;

const m = String(msg.topic || "").match(/^RX-CNT\/([^/]+)\/telemetry$/);
if (!m) return [null, null];

const deviceId = "RX-CNT-" + m[1];
const allCfg = global.get("counterConfig") || {};
const cfg = allCfg[deviceId];
if (!cfg || cfg.enabled !== true) return [null, null];

let data;
try {
    data = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
} catch (e) {
    node.warn(`${deviceId}: invalid JSON`);
    return [null, null];
}

const raw = Number(data?.count);
if (
    !Number.isInteger(raw) ||
    raw < 0 ||
    raw > 4294967295 ||
    data?.boot_id === undefined ||
    data?.boot_id === null
) {
    node.warn(`${deviceId}: invalid payload`);
    return [null, null];
}

const boot = String(data.boot_id);

let counters = flow.get("counters") || {};
let state = counters[deviceId];
if (!state) return [null, null];

const now = Date.now();
state.lastSeen = now;

let delta = 0;
let eventType = "heartbeat";

// previousRaw + previousBootId are restored ONLY from the current shift.
// If there is no trustworthy current-shift baseline, the first MQTT
// message becomes a baseline and is not added to the shift count.
if (
    state.previousRaw === null ||
    state.previousRaw === undefined ||
    state.previousBootId === null ||
    state.previousBootId === undefined
) {
    delta = 0;
    eventType = "initial_sync";
}
else if (boot !== String(state.previousBootId)) {
    // A valid current-shift state existed, but the ESP rebooted.
    // The new raw counter started from zero, therefore its current raw
    // value represents counts after that reboot.
    delta = raw;
    eventType = "new_boot";
}
else if (raw >= Number(state.previousRaw)) {
    delta = raw - Number(state.previousRaw);
    eventType = delta > 0 ? "count" : "heartbeat";
}
else {
    delta = 0;
    eventType = "counter_rollback";
}

if (!Number.isFinite(delta) || delta < 0 || delta > 10000) {
    delta = 0;
    eventType = "rejected_delta";
}

if (delta > 0) {
    state.shiftCount = Number(state.shiftCount || 0) + delta;
    state.deviceCount = Number(state.deviceCount || 0) + delta;
    state.lastSignal = now;
}

state.previousRaw = raw;
state.previousBootId = boot;

counters[deviceId] = state;
flow.set("counters", counters);

const allLineSettings = global.get("lineSettings") || {};
const lineSettings =
    allLineSettings[cfg.line] ||
    allLineSettings[String(cfg.line).toLowerCase()] ||
    {};

const tileSize = lineSettings.tileSize ?? "unknown";
const designCode = lineSettings.designCode ?? "Not Assigned";
const tileCode = lineSettings.tileCode ?? "unknown";
const productionRunId = String(lineSettings.productionRunId || "");

const display = {
    topic: cfg.displayTopic || `display/${deviceId}/shiftCount`,
    payload: JSON.stringify({
        device: deviceId,
        line: cfg.line,
        shift: state.shiftName,
        shiftDate: state.shiftDate,
        count: state.shiftCount
    })
};

const influx = {
    payload: [
        {
            shift_count: Number(state.shiftCount || 0),
            device_count: Number(state.deviceCount || 0),
            raw_count: Number(raw),
            count_delta: Number(delta),
            boot_id: String(boot),
            last_signal: Number(state.lastSignal || 0)
        },
        {
            device: deviceId,
            line: String(cfg.line || deviceId),
            shift: String(state.shiftName || ""),
            shiftDate: String(state.shiftDate || ""),
            tileSize: String(tileSize),
            designCode: String(designCode),
            productionRunId: productionRunId,
            tileCode: String(tileCode),
            eventType: String(eventType)
        }
    ]
};

node.status({
    fill: delta > 0 ? "green" : "blue",
    shape: delta > 0 ? "dot" : "ring",
    text: `${deviceId} +${delta} shift=${state.shiftCount} raw=${raw}`
});

return [display, influx];

const m =
    String(msg.topic || "")
        .match(/^RX-CNT\/([^/]+)\/status$/);

if (!m) {
    return null;
}


// ============================================================
// DEVICE ID
// RX-CNT/1000/status -> RX-CNT-1000
// ============================================================

const id =
    "RX-CNT-" + m[1];


// ============================================================
// CONFIG
// ============================================================

const cfg =
    global.get("counterConfig") || {};


// Ignore completely unknown devices
if (!cfg[id]) {

    node.warn(
        `[STATUS] Unknown device: ${id}`
    );

    return null;
}


// ============================================================
// GET RUNTIME COUNTER STATE
// ============================================================

let counters =
    flow.get("counters") || {};


// ============================================================
// IMPORTANT:
//
// Status MQTT message may arrive before counter restore.
//
// Do NOT discard the status.
//
// Create a minimal runtime state if it does not exist yet.
// Restore logic can later populate the remaining properties.
// ============================================================

if (!counters[id]) {

    counters[id] = {

        rawCount: 0,

        shiftCount: 0,

        deviceCount: 0,

        bootId: null,

        lastSignal: null,

        lastSeen: null,

        sensorStatus: "Unknown",

        shiftName: null,

        shiftDate: null
    };
}


// ============================================================
// PARSE MQTT STATUS
//
// Supports:
//
// online
// offline
//
// "online"
// "offline"
//
// {"status":"online"}
// {"status":"offline"}
// ============================================================

let statusValue = msg.payload;


// Buffer -> string
if (Buffer.isBuffer(statusValue)) {

    statusValue =
        statusValue.toString();
}


// Try JSON if payload is string
if (typeof statusValue === "string") {

    const raw =
        statusValue.trim();

    try {

        const parsed =
            JSON.parse(raw);

        if (
            parsed &&
            typeof parsed === "object"
        ) {

            statusValue =
                parsed.status ??
                parsed.state ??
                parsed.sensorStatus ??
                raw;

        } else {

            statusValue =
                parsed;
        }

    } catch (e) {

        // Normal plain-text MQTT message
        statusValue =
            raw;
    }
}


// Object payload
else if (
    statusValue &&
    typeof statusValue === "object"
) {

    statusValue =
        statusValue.status ??
        statusValue.state ??
        statusValue.sensorStatus ??
        "Unknown";
}


// ============================================================
// NORMALIZE STATUS
// ============================================================

const v =
    String(
        statusValue ?? ""
    )
        .trim()
        .toLowerCase();


let sensorStatus =
    "Unknown";


if (
    v === "online" ||
    v === "connected" ||
    v === "1" ||
    v === "true"
) {

    sensorStatus =
        "Online";
}

else if (
    v === "offline" ||
    v === "disconnected" ||
    v === "0" ||
    v === "false"
) {

    sensorStatus =
        "Offline";
}


// ============================================================
// SAVE STATUS
// ============================================================

counters[id].sensorStatus =
    sensorStatus;


// A status message itself confirms that Node-RED received
// communication from the MQTT broker/device status topic.
counters[id].lastSeen =
    Date.now();


flow.set(
    "counters",
    counters
);


// ============================================================
// DEBUG OUTPUT
// ============================================================

msg.payload = {

    device: id,

    receivedStatus:
        statusValue,

    sensorStatus:
        sensorStatus,

    lastSeen:
        counters[id].lastSeen
};


return msg;

const counterConfig =
    global.get("counterConfig") || {};

const globalLineSettings =
    global.get("lineSettings") || {};


// ============================================================
// WAIT UNTIL GLOBAL CONFIGURATION IS READY
// ============================================================

if (
    global.get("settingsReady") !== true ||
    global.get("counterConfigReady") !== true
) {

    node.status({
        fill: "yellow",
        shape: "ring",
        text: "waiting for global configuration"
    });

    return null;
}


if (
    Object.keys(counterConfig).length === 0
) {

    node.status({
        fill: "red",
        shape: "ring",
        text: "no counters configured"
    });

    return null;
}


// ============================================================
// RESTORE FLAGS
// ============================================================

flow.set(
    "counterRestoreReady",
    false
);

flow.set(
    "downtimeRestoreReady",
    false
);

flow.set(
    "pendingCounterTelemetry",
    {}
);


// ============================================================
// IMPORTANT:
//
// Preserve existing runtime communication information.
//
// MQTT retained status may arrive BEFORE this restore function.
//
// Previously:
//
// const counters = {};
//
// caused sensorStatus = Online to be destroyed and replaced
// with Unknown.
//
// We therefore read the existing counter state first.
// ============================================================

const existingCounters =
    flow.get("counters") || {};

const existingDowntimeStates =
    flow.get("downtimeStates") || {};


// New restore objects
const counters = {};

const downtimeStates = {};


// ============================================================
// BUILD COUNTER RUNTIME STATE
// ============================================================

for (
    const [deviceId, cfg]
    of Object.entries(counterConfig)
) {

    if (!cfg.enabled) {
        continue;
    }


    const existing =
        existingCounters[deviceId] || {};


    counters[deviceId] = {

        // ----------------------------------------------------
        // These values will be restored from InfluxDB
        // ----------------------------------------------------

        shiftCount: 0,

        deviceCount: 0,

        previousRaw: null,

        previousBootId: null,

        shiftName: null,

        shiftDate: null,


        // ----------------------------------------------------
        // PRESERVE MQTT COMMUNICATION STATE
        // ----------------------------------------------------

        lastSeen:
            existing.lastSeen ?? null,

        sensorStatus:
            existing.sensorStatus ??
            "Unknown",


        // ----------------------------------------------------
        // lastSignal will be restored from InfluxDB.
        //
        // Preserve it temporarily so status logic is not
        // unnecessarily lost while restore is in progress.
        // ----------------------------------------------------

        lastSignal:
            existing.lastSignal ?? null
    };


    // ========================================================
    // PRESERVE CURRENT DOWNTIME STATE TEMPORARILY
    // ========================================================

    const existingDown =
        existingDowntimeStates[deviceId] || {};


    downtimeStates[deviceId] = {

    status:
        existingDown.status ?? null,

    runningSince:
        existingDown.runningSince ?? null,

    lastEventTs:
        existingDown.lastEventTs ?? null,

    lastObservedSignal:
        existingDown.lastObservedSignal ?? null,

    pendingShiftRecovery:
        existingDown.pendingShiftRecovery ?? null
    };
}


// ============================================================
// SHIFT INFORMATION
// ============================================================

function getShiftInfo(
    timestamp = Date.now()
) {

    const p = {};


    for (
        const x
        of new Intl.DateTimeFormat(
            "en-CA",
            {
                timeZone:
                    "Asia/Colombo",

                year:
                    "numeric",

                month:
                    "2-digit",

                day:
                    "2-digit",

                hour:
                    "2-digit",

                hourCycle:
                    "h23"
            }
        ).formatToParts(
            new Date(timestamp)
        )
    ) {

        if (
            x.type !== "literal"
        ) {

            p[x.type] =
                x.value;
        }
    }


    const y =
        Number(p.year);

    const m =
        Number(p.month);

    const d =
        Number(p.day);

    const h =
        Number(p.hour);


    const fmt =
        (yy, mm, dd) =>
            `${String(yy).padStart(4, "0")}-${String(mm).padStart(2, "0")}-${String(dd).padStart(2, "0")}`;


    let shiftName;

    let shiftDate;

    let startIso;

    let endIso;


    // ========================================================
    // 06-14
    // ========================================================

    if (
        h >= 6 &&
        h < 14
    ) {

        shiftName =
            "06-14";

        shiftDate =
            fmt(
                y,
                m,
                d
            );

        startIso =
            `${shiftDate}T06:00:00+05:30`;

        endIso =
            `${shiftDate}T14:00:00+05:30`;
    }


    // ========================================================
    // 14-22
    // ========================================================

    else if (
        h >= 14 &&
        h < 22
    ) {

        shiftName =
            "14-22";

        shiftDate =
            fmt(
                y,
                m,
                d
            );

        startIso =
            `${shiftDate}T14:00:00+05:30`;

        endIso =
            `${shiftDate}T22:00:00+05:30`;
    }


    // ========================================================
    // 22-06 BEFORE MIDNIGHT
    // ========================================================

    else if (
        h >= 22
    ) {

        shiftName =
            "22-06";

        shiftDate =
            fmt(
                y,
                m,
                d
            );


        const dt =
            new Date(
                Date.UTC(
                    y,
                    m - 1,
                    d
                )
            );

        dt.setUTCDate(
            dt.getUTCDate() + 1
        );


        const next =
            dt
                .toISOString()
                .slice(0, 10);


        startIso =
            `${shiftDate}T22:00:00+05:30`;

        endIso =
            `${next}T06:00:00+05:30`;
    }


    // ========================================================
    // 22-06 AFTER MIDNIGHT
    // ========================================================

    else {

        shiftName =
            "22-06";


        const dt =
            new Date(
                Date.UTC(
                    y,
                    m - 1,
                    d
                )
            );


        dt.setUTCDate(
            dt.getUTCDate() - 1
        );


        shiftDate =
            dt
                .toISOString()
                .slice(0, 10);


        startIso =
            `${shiftDate}T22:00:00+05:30`;


        endIso =
            `${fmt(y, m, d)}T06:00:00+05:30`;
    }


    return {

        shiftName,

        shiftDate,

        startMs:
            new Date(
                startIso
            ).getTime(),

        endMs:
            new Date(
                endIso
            ).getTime(),

        startIso,

        endIso
    };
}


// ============================================================
// CURRENT SHIFT
// ============================================================

const currentShift =
    getShiftInfo();


for (
    const deviceId
    of Object.keys(counters)
) {

    counters[deviceId].shiftName =
        currentShift.shiftName;

    counters[deviceId].shiftDate =
        currentShift.shiftDate;
}


// ============================================================
// SAVE INITIAL RESTORE STATE
// ============================================================

flow.set(
    "counters",
    counters
);

flow.set(
    "downtimeStates",
    downtimeStates
);


// ============================================================
// PASS SHIFT INFORMATION THROUGH RESTORE FLOW
// ============================================================

msg.restoreShiftName =
    currentShift.shiftName;

msg.restoreShiftDate =
    currentShift.shiftDate;

msg.restoreShiftStartIso =
    currentShift.startIso;

msg.restoreShiftEndIso =
    currentShift.endIso;


// ============================================================
// ENABLED DEVICES
// ============================================================

const devices =
    Object.entries(
        counterConfig
    )
        .filter(
            ([, c]) =>
                c.enabled
        )
        .map(
            ([id]) =>
                `"${id}"`
        )
        .join(", ");


// ============================================================
// RESTORE LONG-TERM DEVICE STATE FROM INFLUXDB
//
// IMPORTANT:
// device_count and last_signal may safely come from older shifts.
// raw_count and boot_id MUST NOT be restored here.
// ============================================================

msg.query = `

from(bucket: "RCLH")

  |> range(start: -1h)

  |> filter(fn: (r) =>
      r._measurement == "tile_events"
  )

  |> filter(fn: (r) =>
      contains(
          value: r.device,
          set: [${devices}]
      )
  )

  |> filter(fn: (r) =>
      r._field == "device_count" or
      r._field == "last_signal"
  )

  |> group(
      columns: [
          "device",
          "_field"
      ]
  )

  |> last()

`;

// ============================================================
// NODE STATUS
// ============================================================

node.status({

    fill:
        "yellow",

    shape:
        "ring",

    text:
        "restoring"
});


return msg;

let counters = flow.get("counters") || {};
const cfg = global.get("counterConfig") || {};
const rows = Array.isArray(msg.payload) ? msg.payload : [];

// ============================================================
// RESTORE LONG-TERM DEVICE STATE ONLY
// ============================================================

for (const row of rows) {
    const id = row.device;

    if (!id || !cfg[id] || !counters[id]) {
        continue;
    }

    if (row._field === "device_count") {
        const v = Number(row._value);

        if (Number.isFinite(v)) {
            counters[id].deviceCount = v;
        }
    }
    else if (row._field === "last_signal") {
        const v = Number(row._value);

        if (Number.isFinite(v) && v > 0) {
            counters[id].lastSignal = v;
        }
    }
}

flow.set("counters", counters);


// ============================================================
// CURRENT SHIFT INFORMATION
// ============================================================

const currentShift =
    String(msg.restoreShiftName || "");

const currentShiftDate =
    String(msg.restoreShiftDate || "");

const currentShiftStartIso =
    String(msg.restoreShiftStartIso || "");

if (
    !currentShift ||
    !currentShiftDate ||
    !currentShiftStartIso
) {
    node.error(
        "Missing restore shift information",
        msg
    );

    return null;
}


// ============================================================
// ENABLED DEVICES
// ============================================================

const devices =
    Object.entries(cfg)
        .filter(([, c]) => c.enabled === true)
        .map(([id]) => `"${id}"`)
        .join(", ");


// ============================================================
// RESTORE CURRENT SHIFT STATE ONLY
//
// CRITICAL DEPLOY-JUMP FIX:
// shift_count, raw_count and boot_id are all taken from the
// current shift/date only.
//
// If the current shift has no telemetry yet, this query returns
// nothing for that device. The next function leaves previousRaw
// and previousBootId as null so the first MQTT message becomes
// initial_sync with delta = 0.
// ============================================================

msg.query = `
from(bucket: "RCLH")

  |> range(
      start: time(v: "${currentShiftStartIso}")
  )

  |> filter(fn: (r) =>
      r._measurement == "tile_events"
  )

  |> filter(fn: (r) =>
      contains(
          value: r.device,
          set: [${devices}]
      )
  )

  |> filter(fn: (r) =>
      r.shift == "${currentShift}"
  )

  |> filter(fn: (r) =>
      r.shiftDate == "${currentShiftDate}"
  )

  |> filter(fn: (r) =>
      r._field == "shift_count" or
      r._field == "raw_count" or
      r._field == "boot_id"
  )

  |> group(
      columns: [
          "device",
          "_field"
      ]
  )

  |> last()
`;

node.status({
    fill: "yellow",
    shape: "ring",
    text:
        `restore current shift ${currentShiftDate} ${currentShift}`
});

return msg;

let counters = flow.get("counters") || {};
const cfg = global.get("counterConfig") || {};
const rows = Array.isArray(msg.payload) ? msg.payload : [];

const currentShift =
    String(msg.restoreShiftName || "");

const currentShiftDate =
    String(msg.restoreShiftDate || "");


// ============================================================
// SAFE DEFAULT FOR EVERY ENABLED COUNTER
//
// No current-shift record means:
//   shiftCount = 0
//   previousRaw = null
//   previousBootId = null
//
// Therefore the first MQTT message becomes a baseline and cannot
// add an old previous-shift raw difference.
// ============================================================

for (const id of Object.keys(counters)) {
    counters[id].shiftName =
        currentShift;

    counters[id].shiftDate =
        currentShiftDate;

    counters[id].shiftCount =
        0;

    counters[id].previousRaw =
        null;

    counters[id].previousBootId =
        null;
}


// ============================================================
// RESTORE CURRENT SHIFT FIELDS
// ============================================================

for (const row of rows) {

    const id = row.device;

    if (
        !id ||
        !counters[id] ||
        !cfg[id] ||
        cfg[id].enabled !== true
    ) {
        continue;
    }

    if (
        String(row.shift || "") !== currentShift ||
        String(row.shiftDate || "") !== currentShiftDate
    ) {
        continue;
    }

    if (row._field === "shift_count") {

        const v =
            Number(row._value);

        if (
            Number.isFinite(v) &&
            v >= 0
        ) {
            counters[id].shiftCount =
                v;
        }
    }

    else if (row._field === "raw_count") {

        const v =
            Number(row._value);

        if (
            Number.isFinite(v) &&
            v >= 0 &&
            v <= 4294967295
        ) {
            counters[id].previousRaw =
                v;
        }
    }

    else if (row._field === "boot_id") {

        if (
            row._value !== undefined &&
            row._value !== null &&
            String(row._value) !== ""
        ) {
            counters[id].previousBootId =
                String(row._value);
        }
    }
}

flow.set("counters", counters);


// ============================================================
// RESTORE DOWNTIME STATE FROM MONGODB
// ============================================================

const enabledDevices =
    Object.entries(cfg)
        .filter(([, c]) => c.enabled === true)
        .map(([id]) => id);

msg.collection =
    "stoppages";

msg.operation =
    "find";

msg.payload = [
    {
        device: {
            $in: enabledDevices
        }
    },
    {
        sort: {
            _id: -1
        }
    }
];

return msg;

let counters = flow.get("counters") || {};
let downtimeStates = flow.get("downtimeStates") || {};
const cfg = global.get("counterConfig") || {};
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const restoredDevices = new Set();
const now = Date.now();

// Query is sorted newest MongoDB _id first.
// Therefore first document seen for each device is its latest stoppage.
for (const row of rows) {
    const deviceId = row.device;

    if (
        !deviceId ||
        !cfg[deviceId] ||
        restoredDevices.has(deviceId)
    ) {
        continue;
    }

    if (!downtimeStates[deviceId]) {
        downtimeStates[deviceId] = {
            status: null,
            runningSince: null,
            lastEventTs: null,
            lastObservedSignal: null,
            pendingShiftRecovery: null
        };
    }

    const isOpenStop =
        row.downStatus === "STOP_START" &&
        (row.stopStop_ts === null || row.stopStop_ts === undefined);

    if (isOpenStop) {
        downtimeStates[deviceId].status = "Stopped";
        downtimeStates[deviceId].lastEventTs =
            Number(row.stopStart_ts) || null;
    } else {
        downtimeStates[deviceId].status = "Running";
        downtimeStates[deviceId].lastEventTs =
            Number(row.stopStop_ts) || Number(row.stopStart_ts) || null;
    }

    downtimeStates[deviceId].runningSince = null;
    downtimeStates[deviceId].lastObservedSignal =
        Number(counters[deviceId]?.lastSignal || 0) || null;

    restoredDevices.add(deviceId);
}

// Devices with no Mongo stoppage history:
// infer state from the restored last real production signal.
const allLineSettings = global.get("lineSettings") || {};

for (const [deviceId, deviceCfg] of Object.entries(cfg)) {
    if (deviceCfg.enabled !== true) continue;

    if (!downtimeStates[deviceId]) {
        downtimeStates[deviceId] = {
         status: null,
         runningSince: null,
         lastEventTs: null,
         lastObservedSignal: null,
         pendingShiftRecovery: null
        };
    }

    if (restoredDevices.has(deviceId)) continue;

    const lastSignal =
        Number(counters[deviceId]?.lastSignal || 0);

    const lineSettings =
        allLineSettings[deviceCfg.line] ||
        allLineSettings[String(deviceCfg.line).toLowerCase()] ||
        {};

    const stopDelayMs =
        Number(
            lineSettings.stopDelayMs ??
            60000
        );

    const recentProduction =
        lastSignal > 0 &&
        (now - lastSignal) <= stopDelayMs;

    downtimeStates[deviceId].status =
        recentProduction ? "Running" : "Stopped";

    downtimeStates[deviceId].runningSince = null;
    downtimeStates[deviceId].lastEventTs = null;
    downtimeStates[deviceId].lastObservedSignal =
        lastSignal || null;
}

flow.set("downtimeStates", downtimeStates);
flow.set("counterRestoreReady", true);
flow.set("downtimeRestoreReady", true);

