function sizeBreakdown(items, expectedCount){
 const sizes=new Map();let unknownSizeTileCount=0,recordedTileCount=0;
 for(const row of items){
  const count=Number(row.tileCount);
  if(!Number.isFinite(count)||count<0)continue;
  const tileSize=String(row.tileSize||"").trim().toLowerCase().replace(/\s+/g,"").replace(/×/g,"x");
  const dims=tileSize.split('x').map(Number);
  const area=dims.length===2&&dims.every(x=>Number.isFinite(x)&&x>0)?dims[0]*dims[1]/10000:0;
  recordedTileCount+=count;
  if(!area)unknownSizeTileCount+=count;
  const item=sizes.get(tileSize)||{tileSize:tileSize||'Unknown',tileCount:0,production:0};
  item.tileCount+=count;item.production+=count*area;sizes.set(tileSize,item);
 }
 const production=[...sizes.values()].reduce((sum,x)=>sum+x.production,0);
 const round2=x=>Math.round((x+Number.EPSILON)*100)/100;
 const countDifference=Number(expectedCount)-recordedTileCount;
 return {production:round2(production),productionUnit:'m²',
  sizeWiseProduction:[...sizes.values()].map(x=>({...x,production:round2(x.production)})),
  tileSizes:[...sizes.values()].filter(x=>x.tileCount>0).map(x=>x.tileSize),
  multipleTileSizes:[...sizes.values()].filter(x=>x.tileCount>0).length>1,
  recordedTileCount,countDifference,unknownSizeTileCount,
  productionComplete:Number.isFinite(countDifference)&&countDifference===0&&unknownSizeTileCount===0};
}
const meta=msg.summaryMeta||{};
const requestId=String(meta.requestId||"");

if(!requestId) {
    msg.statusCode=500;
    msg.payload={
        success:false,
        error:"Current shift summary request ID is missing"
    };
    return msg;
}

let pending=context.get("currentShiftSummaryPending")||{};
const now=Date.now();

// Clear stale partial requests.
for(const id of Object.keys(pending)){
    const createdAt=Number(pending[id]?.createdAt||0);

    if(createdAt>0 && now-createdAt>30000){
        delete pending[id];
    }
}

if(!pending[requestId]){
    pending[requestId]={
        createdAt:now,
        meta,
        influx:null,
        stops:null
    };
}

const entry=pending[requestId];
entry.meta=meta;

if(msg.summaryPart==="influx"){
    entry.influx=msg.summaryPartPayload||[];
}
else if(msg.summaryPart==="stops"){
    entry.stops=msg.summaryPartPayload||[];
}
else {
    return null;
}

pending[requestId]=entry;
context.set("currentShiftSummaryPending",pending);

if(entry.influx===null || entry.stops===null){
    return null;
}

delete pending[requestId];
context.set("currentShiftSummaryPending",pending);

const rows=(entry.influx||[])
    .filter(row=>row?._value!=null && Number.isFinite(Number(row._value)) && Number.isFinite(Date.parse(row._time)))
    .sort((a,b)=>Date.parse(a._time)-Date.parse(b._time)||Number(a._value)-Number(b._value));
const stops=entry.stops||[];
const c=entry.meta||{};

// ============================================================
// AUTHORITATIVE CURRENT-SHIFT RUNTIME STATE
// ============================================================
const counters=flow.get("counters")||{};
const downtimeStates=flow.get("downtimeStates")||{};
const runtime=counters[c.device]||{};
const runtimeDown=downtimeStates[c.device]||{};

const shiftCount=Math.max(0,Number(runtime.shiftCount||0));
const lastSignal=Number(runtime.lastSignal||0)||null;
const lastSeen=Number(runtime.lastSeen||0)||null;
const sensorStatus=String(runtime.sensorStatus||"Unknown");
const shiftStatus=String(runtimeDown.status||"Unknown");

let speed=0;
const tileSize=String(c.configuredTileSize||"");

// Use only the most recent 60 seconds for current speed, while the
// full row set remains available for current-shift code-wise totals.
const speedCutoff=now-60000;
const speedSamples=rows.filter(row=>{
    const time=new Date(row?._time||0).getTime();
    return Number.isFinite(time) && time>=speedCutoff;
});

if(speedSamples.length>=2){
    const first=speedSamples[0];
    const last=speedSamples[speedSamples.length-1];
    const firstCount=Number(first._value);
    const lastCount=Number(last._value);
    const firstTime=new Date(first._time).getTime();
    const lastTime=new Date(last._time).getTime();
    const elapsedSeconds=(lastTime-firstTime)/1000;

    if(Number.isFinite(firstCount) && Number.isFinite(lastCount) && elapsedSeconds>0){
        speed=Math.max(0,((lastCount-firstCount)/elapsedSeconds)*60);
    }
}

function tileAreaM2(size){
    const d=String(size||"")
        .toLowerCase()
        .replace(/\s+/g,"")
        .split("x")
        .map(Number);

    if(
        d.length!==2 ||
        !d.every(v=>Number.isFinite(v) && v>0)
    ){
        return 0;
    }

    return (d[0]*d[1])/10000;
}

function cleanText(value,fallback){
    const text=String(value??"").trim();
    return text||fallback;
}

function isoTime(value){
    if(value===undefined || value===null || value==="") return null;
    const ms=new Date(value).getTime();
    return Number.isFinite(ms)?new Date(ms).toISOString():null;
}



function classify(stops, from, to, configuredAllowance, nowMs){
 const startMs=new Date(from).getTime(), endMs=new Date(to).getTime(), calcEnd=Math.min(nowMs,endMs);
 const full=Math.max(0,(endMs-startMs)/60000), elapsed=Math.max(0,(calcEnd-startMs)/60000);
 let standardActual=0, additional=0, explicitUnplanned=0, total=0, completed=0, open=false, maximum=0;
 const rows=[];
 for(const row of stops){ const st=Math.max(startMs,Number(row.stopStart_ts)); if(!Number.isFinite(st)) continue; const isOpen=row.stopStop_ts==null; const en=Math.min(calcEnd,isOpen?calcEnd:Number(row.stopStop_ts)); if(!Number.isFinite(en)||en<=st) continue; const d=(en-st)/60000; total+=d; maximum=Math.max(maximum,d); const type=String(row.downtimeType||"unplanned").toLowerCase(); const cat=String(row.plannedCategory||"").toLowerCase(); if(type==="planned"&&cat==="standard") standardActual+=d; else if(type==="planned"&&cat==="additional") additional+=d; else explicitUnplanned+=d; if(isOpen)open=true; else completed++; rows.push({...row,downtimeType:(type==="planned"?"planned":"unplanned"),plannedCategory:(type==="planned"?cat:null),isOpen,durationMinutes:Math.round(d*100)/100}); }
 const allowance=Math.max(0,Number(configuredAllowance||0));
 const standardUsed=allowance>0?Math.min(standardActual,allowance):standardActual, remaining=allowance>0?Math.max(0,allowance-standardUsed):0, excess=allowance>0?Math.max(0,standardActual-allowance):0;
 const standardApplied=standardUsed;
 const planned=standardApplied+additional, unplanned=explicitUnplanned+excess;
 return {rows,total,standardActual,standardUsed,remaining,excess,standardApplied,additional,planned,unplanned,completed,open,maximum,full,elapsed};
}

function round(v,d=2){
    const p=Math.pow(10,d);
    return Math.round((Number(v||0)+Number.EPSILON)*p)/p;
}

// ============================================================
// CURRENT SHIFT CODE-WISE PRODUCTION FROM INFLUX SHIFT_COUNT
// ============================================================
const codeMap=new Map();
const codeTimeline=[];
let previousShiftCount=0;
let activeRun=null;
let ignoredRollbacks=0;

for(const row of rows){
    const currentShiftCount=Number(row._value);
    const delta=currentShiftCount-previousShiftCount;

    // Keep the last valid baseline when a lower/stale value occurs.
    // This is the same rollback protection used by the shift-end flow.
    if(!Number.isFinite(delta) || delta<0){
        ignoredRollbacks+=1;
        continue;
    }

    previousShiftCount=currentShiftCount;
    if(delta===0) continue;

    const designCode=cleanText(row.designCode,"Unknown");
    const rowTileSize=cleanText(row.tileSize,"Unknown").toLowerCase().replace(/\s+/g,"").replace(/×/g,"x");
    const producedAt=isoTime(row._time);
    const key=designCode+"|||"+rowTileSize;
    const rowProduction=delta*tileAreaM2(rowTileSize);

    const item=codeMap.get(key)||{
        sequence:codeMap.size+1,
        designCode,
        tileSize:rowTileSize,
        firstProducedAt:producedAt,
        lastProducedAt:producedAt,
        tileCount:0,
        production:0
    };

    if(!item.firstProducedAt && producedAt) item.firstProducedAt=producedAt;
    if(producedAt) item.lastProducedAt=producedAt;
    item.tileCount+=delta;
    item.production+=rowProduction;
    codeMap.set(key,item);

    // Preserve A -> B -> A as three chronological production runs.
    if(!activeRun || activeRun.key!==key){
        activeRun={
            key,
            sequence:codeTimeline.length+1,
            designCode,
            tileSize:rowTileSize,
            startTime:producedAt,
            endTime:producedAt,
            tileCount:0,
            production:0
        };
        codeTimeline.push(activeRun);
    }

    if(!activeRun.startTime && producedAt) activeRun.startTime=producedAt;
    if(producedAt) activeRun.endTime=producedAt;
    activeRun.tileCount+=delta;
    activeRun.production+=rowProduction;
}

const codeWiseProduction=[...codeMap.values()]
    .map(item=>({
        sequence:item.sequence,
        designCode:item.designCode,
        tileSize:item.tileSize,
        firstProducedAt:item.firstProducedAt,
        lastProducedAt:item.lastProducedAt,
        tileCount:Math.round(item.tileCount),
        production:round(item.production,2)
    }))
    .sort((a,b)=>a.sequence-b.sequence);

const codeWiseProductionTimeline=codeTimeline
    .map(({key,...item})=>({
        ...item,
        tileCount:Math.round(item.tileCount),
        production:round(item.production,2)
    }))
    .sort((a,b)=>a.sequence-b.sequence);

if(ignoredRollbacks>0){
    node.warn(
        `Current shift ${c.device} ${c.date} ${c.shift}: `+
        `${ignoredRollbacks} lower shift_count row(s) ignored`
    );
}

const downtime=classify(stops,c.from,c.to,c.plannedDowntime,now);
const downtimeMinutes=downtime.total;
const plannedDowntimeMinutes=downtime.planned;
const unplannedDowntimeMinutes=downtime.unplanned;
const completedStops=downtime.completed;
const openStop=downtime.open;
const elapsedMinutes=downtime.elapsed;
const configuredPlannedDowntime=Math.max(0,Number(c.plannedDowntime||0));
const appliedPlannedDowntime=plannedDowntimeMinutes;
const plannedProductionMinutes=Math.max(0,elapsedMinutes-plannedDowntimeMinutes);
const actualOperatingMinutes=Math.max(0,elapsedMinutes-downtimeMinutes);
const availability=plannedProductionMinutes>0?(actualOperatingMinutes/plannedProductionMinutes)*100:0;
const configuredLineSpeed=Math.max(0,Number(c.configuredLineSpeed||0));
const targetTiles=configuredLineSpeed*actualOperatingMinutes;
const performance=targetTiles>0?(shiftCount/targetTiles)*100:0;
const quality=100;
const ole=(availability*performance*quality)/10000;
const areaPerTile=tileAreaM2(tileSize);
const productionInfo=sizeBreakdown([...codeMap.values()],shiftCount);
productionInfo.ignoredRollbacks=ignoredRollbacks;
productionInfo.productionComplete=productionInfo.productionComplete && ignoredRollbacks===0;
const targetProduction=targetTiles*areaPerTile;

msg.headers={
    "Content-Type":"application/json",
    "Cache-Control":"no-store"
};

msg.payload={
    success:true,
    source:"live",
    device:c.device,
    line:c.line,
    date:c.date,
    shift:c.shift,

    lineStats:{
        device:c.device,
        lineName:c.line,
        shiftDate:c.date,
        shift:c.shift,

        tileSize,
        tileCount:Math.round(shiftCount),
        ...productionInfo,
        productionSource:"influx-event-sizes",

        // Unique design totals, ordered by first production time.
        codeWiseProduction,
        // Complete chronological runs; preserves A -> B -> A.
        codeWiseProductionTimeline,
        codeWiseUpdatedAt:new Date(now).toISOString(),

        targetTiles:round(targetTiles,0),
        targetProduction:round(targetProduction,2),

        elapsedMinutes:round(elapsedMinutes,2),
        configuredPlannedDowntime:round(configuredPlannedDowntime,2),
        recordedStandardDowntimeMinutes:round(downtime.standardActual,2),
        standardPlannedDowntimeMinutes:round(downtime.standardApplied,2),
        remainingStandardAllowanceMinutes:round(downtime.remaining,2),
        standardExcessDowntimeMinutes:round(downtime.excess,2),
        additionalPlannedDowntimeMinutes:round(downtime.additional,2),
        appliedPlannedDowntime:round(appliedPlannedDowntime,2),
        plannedProductionMinutes:round(plannedProductionMinutes,2),

        totalDowntimeMinutes:round(downtimeMinutes,2),
        plannedDowntimeMinutes:round(plannedDowntimeMinutes,2),
        unplannedDowntimeMinutes:round(unplannedDowntimeMinutes,2),
        unplannedDowntime:round(unplannedDowntimeMinutes,2),
        actualOperatingMinutes:round(actualOperatingMinutes,2),

        completedStops,
        totalStops:stops.length,
        maximumDowntimeMinutes:round(downtime.maximum,2),
        openStop,

        availability:round(availability,2),
        performance:round(performance,2),
        quality:round(quality,2),
        ole:round(ole,2),

        currentSpeed:round(speed,2),
        configuredLineSpeed,
        ratedLineSpeed:configuredLineSpeed,

        shiftStatus,
        sensorStatus,
        lastSignal,
        lastSeen,

        source:"live",
        updatedAt:now
    }
};

return msg;

msg.statusCode=500;
msg.headers={
    "Content-Type":"application/json",
    "Cache-Control":"no-store"
};
msg.payload={
    success:false,
    error:msg.error?.message||"Shift summary query failed"
};
return msg;

const r = msg.summaryRequest;
if (!r) return null;

msg.collection = "stoppages";
msg.operation = "find";

// Shift-boundary logic splits open stoppages at boundaries,
// therefore each stoppage document belongs to exactly one shift.
msg.payload = [
    {
        device: r.device,
        date: r.shiftDate,
        shift: r.shift
    },
    {
        sort: {
            stopStart_ts: 1
        }
    }
];

return msg;

const rows = Array.isArray(msg.payload) ? [...msg.payload] : [];
const r = msg.summaryRequest;

if (!r) return null;

// ========================================================
// GET CONFIGURATION
// ========================================================

const cfgAll = global.get("counterConfig") || {};
const cfg = cfgAll[r.device] || {};

const allSettings = global.get("lineSettings") || {};

const ls =
    allSettings[r.line] ||
    allSettings[String(r.line).toLowerCase()] ||
    {};


const lineSpeed =
    Math.max(
        0,
        Number(
            ls.lineSpeed ??
            cfg.lineSpeed ??
            0
        )
    );


const tileSize =
    String(
        ls.tileSize ??
        cfg.tileSize ??
        ""
    ).trim();


const configuredPlannedDowntime =
    Math.max(
        0,
        Number(
            ls.plannedDowntime ??
            cfg.plannedDowntime ??
            0
        )
    );


// ========================================================
// SHIFT TIME RANGE
// ========================================================

const fromMs =
    new Date(r.fromTime).getTime();

const toMs =
    new Date(r.toTime).getTime();

const now =
    Date.now();


if (
    !Number.isFinite(fromMs) ||
    !Number.isFinite(toMs) ||
    toMs <= fromMs
) {
    node.error(
        "Invalid shift time range",
        msg
    );

    return null;
}


// ========================================================
// HELPERS
// ========================================================

function round(v, n = 2) {

    const p =
        10 ** n;

    return Math.round(
        (Number(v || 0) + Number.EPSILON) * p
    ) / p;
}


function tileAreaM2(size) {

    const d =
        String(size || "")
            .toLowerCase()
            .replace(/\s+/g, "")
            .split("x")
            .map(Number);

    if (
        d.length !== 2 ||
        !d.every(
            v =>
                Number.isFinite(v) &&
                v > 0
        )
    ) {
        return 0;
    }

    // Tile dimensions assumed to be centimetres.
    return (
        d[0] *
        d[1]
    ) / 10000;
}


// ========================================================
// SHIFT TIME
// ========================================================

const calculationEndMs =
    Math.min(
        Math.max(now, fromMs),
        toMs
    );


const fullShiftMinutes =
    Math.max(
        0,
        (toMs - fromMs) / 60000
    );


const elapsedMinutes =
    Math.max(
        0,
        (calculationEndMs - fromMs) / 60000
    );


// ========================================================
// CLASSIFY DOWNTIME
//
// FINAL RULE:
//
// Planned -> Standard
//     Actual recorded duration is planned,
//     but limited by configured standard allowance.
//
//     Any duration above the allowance becomes
//     UNPLANNED.
//
// Planned -> Additional
//     Entire recorded duration is planned.
//
// Everything else
//     Unplanned.
//
// IMPORTANT:
//
// Unused configured standard allowance is NOT
// automatically distributed across the shift.
// ========================================================

let totalDowntimeMinutes = 0;

let standardActualMinutes = 0;
let additionalPlannedMinutes = 0;
let explicitUnplannedMinutes = 0;

let completedStops = 0;
let openStop = false;

let currentOpenStopMinutes = 0;
let maximumDowntimeMinutes = 0;


for (const stop of rows) {

    let start =
        Number(stop.stopStart_ts);

    if (!Number.isFinite(start)) {
        continue;
    }


    // Clamp start to shift boundary.
    start =
        Math.max(
            start,
            fromMs
        );


    const isOpen =
        stop.stopStop_ts === null ||
        stop.stopStop_ts === undefined;


    let end;

    if (isOpen) {

        end =
            calculationEndMs;

    } else {

        end =
            Number(
                stop.stopStop_ts
            );

        if (!Number.isFinite(end)) {
            continue;
        }

        end =
            Math.min(
                end,
                calculationEndMs,
                toMs
            );
    }


    if (end <= start) {
        continue;
    }


    const durationMinutes =
        (end - start) / 60000;


    // ----------------------------------------
    // TOTAL ACTUAL DOWNTIME
    // ----------------------------------------

    totalDowntimeMinutes +=
        durationMinutes;


    maximumDowntimeMinutes =
        Math.max(
            maximumDowntimeMinutes,
            durationMinutes
        );


    // ----------------------------------------
    // CLASSIFICATION
    // ----------------------------------------

    const downtimeType =
        String(
            stop.downtimeType ||
            "unplanned"
        ).toLowerCase();


    const plannedCategory =
        String(
            stop.plannedCategory ||
            ""
        ).toLowerCase();


    if (
        downtimeType === "planned" &&
        plannedCategory === "standard"
    ) {

        standardActualMinutes +=
            durationMinutes;

    }

    else if (
        downtimeType === "planned" &&
        plannedCategory === "additional"
    ) {

        additionalPlannedMinutes +=
            durationMinutes;

    }

    else {

        explicitUnplannedMinutes +=
            durationMinutes;

    }


    // ----------------------------------------
    // STOP COUNTS
    // ----------------------------------------

    if (isOpen) {

        openStop = true;

        currentOpenStopMinutes =
            Math.max(
                currentOpenStopMinutes,
                durationMinutes
            );

    } else {

        completedStops += 1;

    }
}


// ========================================================
// STANDARD PLANNED DOWNTIME
// ========================================================

const allowance =
    configuredPlannedDowntime;


// IMPORTANT:
//
// If allowance = 0,
// manually classified Standard Planned downtime
// remains planned.
//
// This matches the live KPI rule.

const standardUsed =
    allowance > 0
        ? Math.min(
            standardActualMinutes,
            allowance
        )
        : standardActualMinutes;


const remainingStandardAllowance =
    allowance > 0
        ? Math.max(
            0,
            allowance -
            standardUsed
        )
        : 0;


const standardExcess =
    allowance > 0
        ? Math.max(
            0,
            standardActualMinutes -
            allowance
        )
        : 0;



const standardApplied =
    standardUsed;


// ========================================================
// PLANNED / UNPLANNED DOWNTIME
// ========================================================

const plannedDowntimeMinutes =
    standardApplied +
    additionalPlannedMinutes;


// Everything not accepted as planned is unplanned.
//
// This automatically includes:
//     explicit unplanned
//     standard excess

const unplannedDowntimeMinutes =
    Math.max(
        0,
        totalDowntimeMinutes -
        plannedDowntimeMinutes
    );


// // ========================================================
// // PRODUCTION TIME
// // ========================================================

// // Planned production time:
// //
// // Elapsed shift time minus accepted planned downtime.

// const plannedProductionMinutes =
//     Math.max(
//         0,
//         elapsedMinutes -
//         plannedDowntimeMinutes
//     );


// // IMPORTANT:
// //
// // Physical operating time depends ONLY on
// // actual stoppage duration.
// //
// // Planned/unplanned classification does not
// // change physical operating time.

// // ========================================================
// // RUN CONFIRMATION CORRECTION
// // ========================================================
// //
// // STOP_END is confirmed only after the line has been running
// // continuously for requiredRunTimeMs.
// //
// // Tiles are already counted during this confirmation period,
// // while that same period is still included in the recorded
// // downtime. Add it back once for every COMPLETED stop.
// //
// // Open stops are intentionally excluded because they have not
// // completed the recovery-confirmation period yet.

// const requiredRunTimeMs =
//     Math.max(
//         0,
//         Number(
//             ls.requiredRunTimeMs ??
//             cfg.requiredRunTimeMs ??
//             60000
//         )
//     );

// const runConfirmationMinutes =
//     requiredRunTimeMs / 60000;

// const recoveryCorrectionMinutes =
//     completedStops *
//     runConfirmationMinutes;



// const actualOperatingMinutes =
//     Math.max(
//         0,
//         Math.min(
//             elapsedMinutes,
//             elapsedMinutes -
//             totalDowntimeMinutes +
//             recoveryCorrectionMinutes
//         )
//     );


// // ========================================================
// // AVAILABILITY
// // ========================================================

// const availability =
//     plannedProductionMinutes > 0
//         ? (
//             actualOperatingMinutes /
//             (plannedProductionMinutes+recoveryCorrectionMinutes)
//         ) * 100
//         : 0;

// ========================================================
// PRODUCTION TIME
// ========================================================

const plannedProductionMinutes = Math.max(
    0,
    elapsedMinutes - plannedDowntimeMinutes
);

// Stored STOP_END is already backdated to runningSince.
// The confirmation minute is therefore already operating time.
const actualOperatingMinutes = Math.max(
    0,
    Math.min(
        elapsedMinutes,
        elapsedMinutes - totalDowntimeMinutes
    )
);

// ========================================================
// AVAILABILITY
// ========================================================

const availability =
    plannedProductionMinutes > 0
        ? (actualOperatingMinutes / plannedProductionMinutes) * 100
        : 0;


// ========================================================
// PRODUCTION
// ========================================================

const tileCount =
    Math.max(
        0,
        Number(
            r.tileCount || 0
        )
    );


const areaPerTile =
    tileAreaM2(
        tileSize
    );


const production =
    tileCount *
    areaPerTile;


// ========================================================
// TARGET PRODUCTION
//
// Target is based on PHYSICAL OPERATING TIME.
//
// Example:
//
// Operating time = 400 min
// Rated speed    = 12 tiles/min
//
// Target = 4,800 tiles
// ========================================================

const targetTiles =
    lineSpeed > 0
        ? lineSpeed *
          actualOperatingMinutes
        : 0;


const targetProduction =
    targetTiles *
    areaPerTile;


// ========================================================
// PERFORMANCE
// ========================================================

const performance =
    targetTiles > 0
        ? (
            tileCount /
            targetTiles
        ) * 100
        : 0;


// ========================================================
// QUALITY
// ========================================================

// No reject / quality counter is currently available.
// Therefore quality remains 100%.

const quality =
    100;


// ========================================================
// OLE
// ========================================================

const ole =
    (
        availability *
        performance *
        quality
    ) / 10000;


// ========================================================
// BUILD SHIFT SUMMARY
// ========================================================

msg.payload = {

    lineStats: {

        // ----------------------------------------
        // IDENTIFICATION
        // ----------------------------------------

        device:
            r.device,

        lineName:
            r.line,

        machine:
            r.machine || "",

        shift:
            r.shift,

        shiftDate:
            r.shiftDate,

        shiftStart:
            r.fromTime,

        shiftEnd:
            r.toTime,

        status:
            r.shiftStatus ||
            "Unknown",

        // Configuration at the end of this shift. Run IDs inside
        // codeWiseProduction / Timeline identify individual production.
        productionRunId: r.productionRunIdAtShiftEnd || null,
        productionRunStartTime: r.productionRunStartTimeAtShiftEnd || null,


        // ----------------------------------------
        // KPI
        // ----------------------------------------

        ole:
            round(ole),

        availability:
            round(availability),

        performance:
            round(performance),

        quality:
            quality,


        // ----------------------------------------
        // PRODUCTION
        // ----------------------------------------

        tileCount:
            Math.round(tileCount),

        production:
            round(production),

        productionUnit:
            "m²",

        targetTiles:
            round(targetTiles, 0),

        targetProduction:
            round(targetProduction),


        // ----------------------------------------
        // SHIFT TIME
        // ----------------------------------------

        fullShiftMinutes:
            round(fullShiftMinutes),

        elapsedShiftMinutes:
            round(elapsedMinutes),

        plannedProductionMinutes:
            round(
                plannedProductionMinutes
            ),

        actualOperatingMinutes:
            round(
                actualOperatingMinutes
            ),


        // ----------------------------------------
        // DOWNTIME
        // ----------------------------------------

        totalDowntimeMinutes:
            round(
                totalDowntimeMinutes
            ),

        plannedDowntimeMinutes:
            round(
                plannedDowntimeMinutes
            ),

        unplannedDowntimeMinutes:
            round(
                unplannedDowntimeMinutes
            ),


        // ----------------------------------------
        // STANDARD PLANNED
        // ----------------------------------------

        configuredPlannedDowntime:
            round(
                configuredPlannedDowntime
            ),

        recordedStandardDowntimeMinutes:
            round(
                standardActualMinutes
            ),

        standardPlannedDowntimeMinutes:
            round(
                standardApplied
            ),

        remainingStandardAllowanceMinutes:
            round(
                remainingStandardAllowance
            ),

        standardExcessDowntimeMinutes:
            round(
                standardExcess
            ),


        // ----------------------------------------
        // ADDITIONAL PLANNED
        // ----------------------------------------

        additionalPlannedDowntimeMinutes:
            round(
                additionalPlannedMinutes
            ),

        appliedPlannedDowntime:
            round(
                plannedDowntimeMinutes
            ),


        // ----------------------------------------
        // STOP INFORMATION
        // ----------------------------------------

        completedStops:
            completedStops,

        totalStops:
            rows.length,

        openStop:
            openStop,

        currentOpenStopMinutes:
            round(
                currentOpenStopMinutes
            ),

        maximumDowntimeMinutes:
            round(
                maximumDowntimeMinutes
            ),


        // ----------------------------------------
        // LINE CONFIGURATION
        // ----------------------------------------

        ratedLineSpeed:
            lineSpeed,

        tileSize:
            tileSize,

        stopDelayMs:
            Number(
                ls.stopDelayMs ??
                cfg.stopDelayMs ??
                60000
            ),

        maxPulseGapMs:
            Number(
                ls.maxPulseGapMs ??
                cfg.maxPulseGapMs ??
                10000
            ),

        requiredRunTimeMs:
            Number(
                ls.requiredRunTimeMs ??
                cfg.requiredRunTimeMs ??
                60000
            ),


        // Availability may legitimately exceed
        // 100% under this planned-downtime model.
        availabilityMayExceed100:
            true,


        source:
            "shift-summary",

        updatedAt:
            new Date().toISOString()
    }
};


// ========================================================
// SAVE TO MONGODB
// ========================================================

msg.collection =
    "shifts";

msg.operation =
    "insertOne";


return msg;

const req = msg.summaryRequest;

if (
    !req ||
    !req.device ||
    !req.shift ||
    !req.shiftDate ||
    !req.fromTime ||
    !req.toTime
) {
    node.warn(
        "Code-wise enrichment skipped: summaryRequest is missing"
    );
    return null;
}

function esc(v) {
    return String(v ?? "")
        .replace(/\\/g, "\\\\")
        .replace(/"/g, '\\"');
}

msg.codeWiseTarget = {
    device: req.device,
    line: req.line,
    shift: req.shift,
    shiftDate: req.shiftDate,
    fromTime: req.fromTime,
    toTime: req.toTime,
    productionRunIdAtShiftEnd: req.productionRunIdAtShiftEnd || null,
    productionRunStartTimeAtShiftEnd: req.productionRunStartTimeAtShiftEnd || null
};

const device = esc(req.device);
const shift = esc(req.shift);
const shiftDate = esc(req.shiftDate);
const fromTime = esc(req.fromTime);
const toTime = esc(req.toTime);

// Read the completed shift's cumulative shift_count records.
// Difference calculation and design-code grouping are performed
// in the next Node-RED function for better Flux compatibility.
msg.query = `
from(bucket: "RCLH")
  |> range(
      start: time(v: "${fromTime}"),
      stop: time(v: "${toTime}")
  )
  |> filter(fn: (r) =>
      r["_measurement"] == "tile_events" and
      r["_field"] == "shift_count" and
      r["device"] == "${device}" and
      r["shift"] == "${shift}" and
      r["shiftDate"] == "${shiftDate}"
  )
  |> group(columns: ["device", "shift", "shiftDate"])
  |> sort(columns: ["_time"])
  |> keep(
      columns: [
          "_time",
          "_value",
          "designCode",
          "tileSize",
          "productionRunId",
          "productionRunStartTime"
      ]
  )
`;

node.warn(
    `Code-wise shift_count query: ${req.device} | ` +
    `${req.shiftDate} | ${req.shift} | ` +
    `${req.fromTime} -> ${req.toTime}`
);

return msg;

const rows = (Array.isArray(msg.payload) ? msg.payload : [])
    .filter(row => Number.isFinite(Number(row?._value)))
    .sort((a, b) => {
        const ta = new Date(a?._time || 0).getTime();
        const tb = new Date(b?._time || 0).getTime();
        return ta - tb;
    });

const target = msg.codeWiseTarget;

if (!target) {
    node.error("Code-wise target identity was lost", msg);
    return null;
}

function round(v, n = 2) {
    const p = 10 ** n;
    return Math.round((Number(v || 0) + Number.EPSILON) * p) / p;
}

function tileAreaM2(size) {
    const d = String(size || "")
        .toLowerCase()
        .replace(/\s+/g, "")
        .split("x")
        .map(Number);

    if (
        d.length !== 2 ||
        !d.every(v => Number.isFinite(v) && v > 0)
    ) {
        return 0;
    }

    return (d[0] * d[1]) / 10000;
}

function cleanText(value, fallback) {
    const text = String(value ?? "").trim();
    return text || fallback;
}

function isoTime(value) {
    if (value === undefined || value === null || value === "") return null;
    const ms = new Date(value).getTime();
    return Number.isFinite(ms) ? new Date(ms).toISOString() : null;
}

const aggregateMap = new Map();
const timeline = [];

let previousShiftCount = 0;
let ignoredRollbacks = 0;
let activeRun = null;

for (const row of rows) {
    const currentShiftCount = Number(row._value);
    const delta = currentShiftCount - previousShiftCount;

    // Keep the last valid cumulative value if a lower/stale value
    // appears. This prevents the next valid row creating a spike.
    if (!Number.isFinite(delta) || delta < 0) {
        ignoredRollbacks += 1;

        node.warn(
            "Completed-shift shift_count rollback ignored: " +
            "previous=" + previousShiftCount +
            ", current=" + currentShiftCount +
            ", time=" + String(row?._time || "")
        );

        continue;
    }

    previousShiftCount = currentShiftCount;

    if (delta === 0) {
        continue;
    }

    const designCode = cleanText(row.designCode, "Unknown");
    const tileSize = cleanText(row.tileSize, "Unknown");
    const producedAt = isoTime(row._time);
    const production = delta * tileAreaM2(tileSize);

    // Prefer immutable tags written alongside each counter event.
    // Without these tags, a global setting read at shift end cannot
    // determine which earlier run produced a tile before a changeover.
    let productionRunId = cleanText(row.productionRunId, "") || null;
    let productionRunStartTime = isoTime(row.productionRunStartTime);
    let runIdSource = productionRunId ? "influx-event" : "unresolved";

    // Conservative fallback for legacy telemetry: only associate a row
    // with the end-of-shift run if the event is on/after its start AND
    // its tile size agrees. Do not guess the earlier production run.
    const fallbackStart = isoTime(target.productionRunStartTimeAtShiftEnd);
    const fallbackId = target.productionRunIdAtShiftEnd || null;
    if (!productionRunId && fallbackId && fallbackStart &&
        producedAt && Date.parse(producedAt) >= Date.parse(fallbackStart)) {
        const settings = global.get("lineSettings") || {};
        const ls = settings[target.line] || settings[String(target.line || "").toLowerCase()] || {};
        if (String(ls.tileSize || "").trim() === tileSize &&
            String(ls.productionRunId || "") === String(fallbackId)) {
            productionRunId = String(fallbackId);
            productionRunStartTime = fallbackStart;
            runIdSource = "shift-end-fallback";
        }
    }

    const key = JSON.stringify([designCode, tileSize, productionRunId, productionRunStartTime]);

    // ----------------------------------------------------------
    // AGGREGATED TOTAL PER DESIGN CODE + TILE SIZE
    // sequence records when this design was first produced.
    // ----------------------------------------------------------
    const aggregate = aggregateMap.get(key) || {
        sequence: aggregateMap.size + 1,
        designCode,
        tileSize,
        productionRunId,
        productionRunStartTime,
        runIdSource,
        firstProducedAt: producedAt,
        lastProducedAt: producedAt,
        tileCount: 0,
        production: 0
    };

    if (!aggregate.firstProducedAt && producedAt) {
        aggregate.firstProducedAt = producedAt;
    }

    if (producedAt) {
        aggregate.lastProducedAt = producedAt;
    }

    aggregate.tileCount += delta;
    aggregate.production += production;
    aggregateMap.set(key, aggregate);

    // ----------------------------------------------------------
    // CHRONOLOGICAL PRODUCTION RUNS
    // A -> B -> A is saved as three separate timeline entries.
    // ----------------------------------------------------------
    if (!activeRun || activeRun.key !== key) {
        activeRun = {
            key,
            sequence: timeline.length + 1,
            designCode,
            tileSize,
            productionRunId,
            productionRunStartTime,
            runIdSource,
            startTime: producedAt,
            endTime: producedAt,
            tileCount: 0,
            production: 0
        };

        timeline.push(activeRun);
    }

    if (!activeRun.startTime && producedAt) {
        activeRun.startTime = producedAt;
    }

    if (producedAt) {
        activeRun.endTime = producedAt;
    }

    activeRun.tileCount += delta;
    activeRun.production += production;
}

// Unique design-code totals, ordered by first production time.
msg.codeWiseProduction = [...aggregateMap.values()]
    .map(item => ({
        sequence: item.sequence,
        designCode: item.designCode,
        tileSize: item.tileSize,
        productionRunId: item.productionRunId,
        productionRunStartTime: item.productionRunStartTime,
        runIdSource: item.runIdSource,
        firstProducedAt: item.firstProducedAt,
        lastProducedAt: item.lastProducedAt,
        tileCount: Math.round(item.tileCount),
        production: round(item.production)
    }))
    .sort((a, b) => a.sequence - b.sequence);

// Every chronological production run. Use this array for a chart
// where the left side is the first run and the right side is the last.
msg.codeWiseProductionTimeline = timeline
    .map(({key, ...item}) => ({
        ...item,
        tileCount: Math.round(item.tileCount),
        production: round(item.production)
    }))
    .sort((a, b) => a.sequence - b.sequence);

const calculatedTileCount = msg.codeWiseProduction.reduce(
    (sum, item) => sum + Number(item.tileCount || 0),
    0
);

node.status({
    fill: ignoredRollbacks > 0 ? "yellow" : "green",
    shape: ignoredRollbacks > 0 ? "ring" : "dot",
    text:
        rows.length + " rows -> " +
        msg.codeWiseProduction.length + " codes, " +
        msg.codeWiseProductionTimeline.length + " runs, " +
        calculatedTileCount + " tiles"
});

return msg;

// const target = msg.codeWiseTarget;

// if (!target || !target.device || !target.shift || !target.shiftDate) {
//     node.error("Cannot update shift: codeWiseTarget is invalid", msg);
//     return null;
// }

// msg.collection = "shifts";
// msg.mode = "collection";
// msg.operation = "updateOne";

// msg.payload = [
//     {
//         "lineStats.device": target.device,
//         "lineStats.shift": target.shift,
//         "lineStats.shiftDate": target.shiftDate
//     },
//     {
//         $set: {
//             // Aggregated unique design totals in first-produced order.
//             "lineStats.codeWiseProduction":
//                 Array.isArray(msg.codeWiseProduction)
//                     ? msg.codeWiseProduction
//                     : [],

//             // Complete run order. This preserves A -> B -> A.
//             "lineStats.codeWiseProductionTimeline":
//                 Array.isArray(msg.codeWiseProductionTimeline)
//                     ? msg.codeWiseProductionTimeline
//                     : [],

//             "lineStats.codeWiseUpdatedAt": new Date().toISOString()
//         }
//     }
// ];

// return msg;

const target = msg.codeWiseTarget;

if (!target || !target.device || !target.shift || !target.shiftDate) {
    node.error("Cannot update shift: codeWiseTarget is invalid", msg);
    return null;
}

const codeWise = Array.isArray(msg.codeWiseProduction)
    ? msg.codeWiseProduction
    : [];

const timeline = Array.isArray(msg.codeWiseProductionTimeline)
    ? msg.codeWiseProductionTimeline
    : [];

function round(value, decimals = 2) {
    const p = 10 ** decimals;
    return Math.round((value + Number.EPSILON) * p) / p;
}

function normalizeSize(value) {
    return String(value ?? "")
        .trim()
        .toLowerCase()
        .replace(/\s+/g, "")
        .replace(/×/g, "x");
}

function tileAreaM2(size) {
    const dimensions = size.split("x").map(Number);

    if (
        dimensions.length !== 2 ||
        !dimensions.every(n => Number.isFinite(n) && n > 0)
    ) {
        return null;
    }

    // Dimensions are in centimetres.
    return dimensions[0] * dimensions[1] / 10000;
}

const sizes = new Map();

for (const row of codeWise) {
    const tileSize = normalizeSize(row.tileSize);
    const tileCount = Number(row.tileCount);
    const area = tileAreaM2(tileSize);

    if (
        area === null ||
        !Number.isFinite(tileCount) ||
        tileCount < 0
    ) {
        node.error(
            "Cannot calculate size-wise production: invalid tile size/count",
            msg
        );
        return null;
    }

    if (!sizes.has(tileSize)) {
        sizes.set(tileSize, {
            tileSize,
            tileCount: 0,
            production: 0,
            productionUnit: "m²"
        });
    }

    const item = sizes.get(tileSize);

    item.tileCount += tileCount;
    item.production += tileCount * area;
}

const sizeWiseProduction = [...sizes.values()].map(item => ({
    ...item,
    production: round(item.production)
}));

// Calculate the total before rounding individual size totals.
const totalProduction = round(
    [...sizes.values()].reduce(
        (sum, item) => sum + item.production,
        0
    )
);

const tileSizes = sizeWiseProduction.map(item => item.tileSize);
const updatedAt = new Date().toISOString();

msg.collection = "shifts";
msg.mode = "collection";
msg.operation = "updateOne";

msg.payload = [
    {
        "lineStats.device": target.device,
        "lineStats.shift": target.shift,
        "lineStats.shiftDate": target.shiftDate
    },
    {
        $set: {
            "lineStats.codeWiseProduction": codeWise,
            "lineStats.codeWiseProductionTimeline": timeline,
            "lineStats.sizeWiseProduction": sizeWiseProduction,

            // All sizes produced during this shift.
            "lineStats.tileSizes": tileSizes,
            "lineStats.multipleTileSizes": tileSizes.length > 1,

            // Correct total m² using each size's actual count.
            "lineStats.production": totalProduction,
            "lineStats.productionUnit": "m²",

            "lineStats.codeWiseUpdatedAt": updatedAt
        }
    }
