        const d = Number(p.day);
        const h = Number(p.hour);

        const fmt = (yy, mm, dd) =>
            `${String(yy).padStart(4, "0")}-${String(mm).padStart(2, "0")}-${String(dd).padStart(2, "0")}`;

        let shiftName;
